import java.io.*;
import java.util.Arrays;

public class Main {
    public static void main(String[] args) throws IOException {
        DataInputStream in = new DataInputStream(new BufferedInputStream(System.in, 1 << 16));
        long limit = readLong(in), window = readLong(in), n = readLong(in);
        long sum = 0, total = 0;
        // Ring buffer of accepted logs with positive size that may still be in the window.
        long[] times = new long[1 << 16];
        int[] sizes = new int[1 << 16];
        int head = 0, count = 0;
        for (long i = 0; i < n; i++) {
            long t = readLong(in); // unsigned 64-bit, stored as its bit pattern
            long size = readLong(in);
            // Expire while t - oldTime > window (unsigned compare, no overflow).
            while (count > 0 && Long.compareUnsigned(t - times[head], window) > 0) {
                sum -= Integer.toUnsignedLong(sizes[head]);
                head = (head + 1) & (times.length - 1);
                count--;
            }
            if (sum + size <= limit) {
                sum += size;
                total += size;
                if (size != 0) {
                    if (count == times.length) {
                        long[] nt = new long[times.length * 2];
                        int[] ns = new int[times.length * 2];
                        for (int j = 0; j < count; j++) {
                            nt[j] = times[(head + j) & (times.length - 1)];
                            ns[j] = sizes[(head + j) & (times.length - 1)];
                        }
                        times = nt;
                        sizes = ns;
                        head = 0;
                    }
                    int tail = (head + count) & (times.length - 1);
                    times[tail] = t;
                    sizes[tail] = (int) size;
                    count++;
                }
            }
        }
        System.out.println(Long.toUnsignedString(total));
    }

    private static long readLong(DataInputStream in) throws IOException {
        int c = in.read();
        while (c != -1 && c <= ' ') c = in.read();
        long x = 0; // wraps like uint64 for values above Long.MAX_VALUE
        while (c > ' ') {
            x = x * 10 + (c - '0');
            c = in.read();
        }
        return x;
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	reader := bufio.NewReaderSize(os.Stdin, 1<<16)
	readInt := func() uint64 {
		c, err := reader.ReadByte()
		for err == nil && c <= ' ' {
			c, err = reader.ReadByte()
		}
		var x uint64
		for err == nil && c > ' ' {
			x = x*10 + uint64(c-'0')
			c, err = reader.ReadByte()
		}
		return x
	}
	limit, window, n := readInt(), readInt(), readInt()
	var sum, total uint64
	// Queue of accepted logs with positive size that may still be in the window.
	times := []uint64{}
	sizes := []uint32{}
	head := 0
	for i := uint64(0); i < n; i++ {
		t, size := readInt(), readInt()
		// t - oldTime > window avoids overflow of oldTime + window.
		for head < len(times) && t-times[head] > window {
			sum -= uint64(sizes[head])
			head++
		}
		if head > 1<<16 && head*2 > len(times) {
			times = append(times[:0], times[head:]...)
			sizes = append(sizes[:0], sizes[head:]...)
			head = 0
		}
		if sum+size <= limit {
			sum += size
			total += size
			if size != 0 {
				times = append(times, t)
				sizes = append(sizes, uint32(size))
			}
		}
	}
	fmt.Println(total)
}
